import os
import time
import hmac
import hashlib
import json
import re
from urllib.parse import unquote, urlparse
from flask import Flask, request, jsonify, abort
import sqlite3

app = Flask(__name__)

# Require the secret to be provided via environment; fail closed if missing.
SECRET_KEY = os.environ.get('API_SECRET')
if not SECRET_KEY:
    raise RuntimeError('API_SECRET environment variable must be set')

DB_PATH = '/var/data/mobile_backend.db'

# Maximum age (in seconds) for a proxy-signed request before it is rejected.
PROXY_SIGNATURE_MAX_AGE = 30

def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn

def verify_proxy_signature(req):
    """Verify request came through our trusted reverse proxy (nginx)"""
    sig = req.headers.get('X-Proxy-Signature')
    timestamp = req.headers.get('X-Proxy-Timestamp')
    if not sig or not timestamp:
        return False
    # Reject stale/replayed requests by validating timestamp freshness.
    try:
        ts = int(timestamp)
    except (ValueError, TypeError):
        return False
    now = int(time.time())
    if abs(now - ts) > PROXY_SIGNATURE_MAX_AGE:
        return False
    payload = f"{req.method}:{req.path}:{timestamp}"
    expected = hmac.new(SECRET_KEY.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return hmac.compare_digest(sig, expected)

def normalize_path(path):
    """Normalize URL path to prevent traversal and encoding tricks.
    The reverse proxy (nginx) performs initial URL decoding before forwarding.
    We decode once to handle any residual encoding, then sanitize."""
    # Decode any percent-encoding that survived the proxy
    decoded = unquote(path)
    # Reject if decoding reveals further encoded sequences (double-encoding attack)
    if '%' in decoded:
        return None
    # Collapse any path traversal attempts
    parts = []
    for segment in decoded.split('/'):
        if segment == '..':
            if parts:
                parts.pop()
        elif segment and segment != '.':
            parts.append(segment)
    return '/' + '/'.join(parts)

def extract_user_id_from_path(normalized_path):
    """Extract user ID from API path like /api/v2/users/<id>/profile"""
    match = re.match(r'^/api/v2/users/([a-zA-Z0-9_-]+)/.*$', normalized_path)
    if match:
        return match.group(1)
    return None

def check_acl(requesting_user, target_user_id):
    """Verify the authenticated user can access the target user's data"""
    if requesting_user == target_user_id:
        return True
    db = get_db()
    cursor = db.execute(
        'SELECT role FROM users WHERE user_id = ?',
        (requesting_user,)
    )
    row = cursor.fetchone()
    db.close()
    if row and row['role'] == 'admin':
        return True
    return False

def authenticate_request(req):
    """Authenticate via Bearer token from mobile client"""
    auth_header = req.headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        return None
    token = auth_header[7:]
    db = get_db()
    cursor = db.execute(
        'SELECT user_id FROM sessions WHERE token = ? AND expires_at > datetime("now")',
        (token,)
    )
    row = cursor.fetchone()
    db.close()
    if row:
        return row['user_id']
    return None

@app.before_request
def before_request_handler():
    """Security middleware: verify proxy and normalize paths"""
    if not request.path.startswith('/health'):
        if not verify_proxy_signature(request):
            abort(403)

@app.route('/api/v2/users/<path:user_path>', methods=['GET'])
def get_user_data(user_path):
    """Retrieve user profile data - used by mobile app"""
    requesting_user = authenticate_request(request)
    if not requesting_user:
        return jsonify({'error': 'unauthorized'}), 401

    # Use Flask's already-parsed path parameter directly for ACL
    # Do NOT re-parse from raw URI to avoid proxy/app path interpretation differences
    path_segments = user_path.split('/')
    target_user_id = path_segments[0] if path_segments else None

    if not target_user_id or not re.match(r'^[a-zA-Z0-9_-]+$', target_user_id):
        return jsonify({'error': 'invalid user id'}), 400

    if not check_acl(requesting_user, target_user_id):
        return jsonify({'error': 'forbidden'}), 403

    db = get_db()
    cursor = db.execute(
        'SELECT user_id, display_name, email, phone, created_at FROM users WHERE user_id = ?',
        (target_user_id,)
    )
    user = cursor.fetchone()
    db.close()

    if not user:
        return jsonify({'error': 'not found'}), 404

    return jsonify(dict(user))

@app.route('/api/v2/users/<user_id>/settings', methods=['PUT'])
def update_user_settings(user_id):
    """Update user settings - mobile app settings screen"""
    requesting_user = authenticate_request(request)
    if not requesting_user:
        return jsonify({'error': 'unauthorized'}), 401

    # Use Flask's route parameter directly - already decoded and matched
    target_user_id = user_id

    if not target_user_id or not re.match(r'^[a-zA-Z0-9_-]+$', target_user_id):
        return jsonify({'error': 'invalid user id'}), 400

    if not check_acl(requesting_user, target_user_id):
        return jsonify({'error': 'forbidden'}), 403

    data = request.get_json()
    if not data:
        return jsonify({'error': 'invalid body'}), 400

    allowed_fields = {'display_name', 'notification_prefs', 'theme'}
    updates = {k: v for k, v in data.items() if k in allowed_fields}

    if updates:
        db = get_db()
        set_clause = ', '.join(f"{k} = ?" for k in updates.keys())
        values = list(updates.values()) + [target_user_id]
        db.execute(f'UPDATE users SET {set_clause} WHERE user_id = ?', values)
        db.commit()
        db.close()

    return jsonify({'status': 'updated'})

@app.route('/health')
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=8080)
